INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-v58-thundercaster', 1, 'NG-C58 Variable Projectile Cannon (1)', 'Explosive shell made for it: 1D6x10 M.D. to a 10 ft (3 m) radius. An S.D.C. object: its normal damage +4D6 S.D.C. (+30 S.D.C. if it weighs 150 lb/67.5 kg or more). An M.D.C. object: its normal damage +2D6 M.D. (+10 M.D. at 150 lb/67.5 kg or more)', 1, '1,400 ft (427 m) with its own artillery shells; 1,000 ft (305 m) with fairly aerodynamic objects such as a fence post or bowling ball; 700 ft (213 m) with objects that are not, such as a brick, a rough log or scrap', 'One shell or object at a time, each shot one melee attack; hand loading and scanning a projectile takes two melee actions', '24 shells: 8 in the auto-loading hopper and 8 in each shoulder store. Improvised projectiles go in one at a time by hand, through the breech or down the muzzle; none may weigh over 300 lb (135 kg), run longer than 4 ft (1.2 m) or exceed 2 ft (0.6 m) across', 'Half the usual strike bonus with its shells or aerodynamic objects; no strike bonus at all, a bare D20, with anything else', 'The Thunder Cannon, over the right shoulder. Anti-fortification, anti-armor and assault, secondarily anti-monster and defense. An air-pressure tube that laser-scans what is loaded, closes the barrel around it and sets the air charge by its size and weight, so it fires its own shells or rocks, logs, bricks, posts, scrap or any object at least the size of a fist. Arc of 180 degrees up and down and 45 degrees side to side; a spotlight and laser distancer sit on top. A loader with Robot or Supernatural P.S. is needed for heavy improvised rounds. Never load an explosive: a live grenade goes off in the barrel, and an impact-fused munition has a 01-33% chance to detonate inside the gun when the air charge hits it (the gun''s own shells excepted).'),
  ('ng-v58-thundercaster', 2, 'NG-R58 Rail Gun', '1D4x10 M.D. per 40 round burst; 1D4 M.D. per single round', 1, '4,000 ft (1,219 m)', 'Each single shot or burst is one melee attack', '50 bursts in all: 400 rounds (10 bursts) inside the arm and a belt-fed back drum of 1,600 (40 bursts). A second 1,600 round drum rides on the back, but swapping it in by hand (the drum weighs 400 lb/180 kg) takes a skilled crew 1D4+2 minutes and an unskilled one 2D4+4', '+1 to strike from the enhanced radar', 'Anti-armor, secondarily assault. A multi-barrel rail gun that forms the right arm, on a joint high on the limb that swings it left, right, up and down; a camera with a 6,000 ft (1,828 m) telescopic lens stands in for a sight. The introduction calls it an NG-404 gatling-style rail gun; this entry''s name and figures are the weapon entry''s.'),
  ('ng-v58-thundercaster', 3, 'NG-L258 Double-Barreled Laser', '3D6 M.D. per single blast; 6D6 M.D. per dual blast', 1, '2,000 ft (610 m)', 'Each single or dual blast is one melee attack', 'Effectively unlimited', '+1 to strike from the enhanced radar', 'Anti-personnel and assault, secondarily defense. A twin laser in the left forearm; single beams pick off infantry or cut, dual beams hit harder.'),
  ('ng-v41-viking', 1, 'NG-41G Automatic Grenade Launcher', 'Per three grenade burst: fragmentation 2D6 M.D. to a 24 ft (7.3 m) radius; high explosive/armor piercing 3D6 M.D. to a 12 ft (3.6 m) radius; plasma 6D6 M.D. to a 24 ft (7.3 m) radius', 1, '1,000 ft (305 m)', 'Each three grenade burst is one melee action/attack', '120 round drum, 40 bursts', NULL, 'Anti-personnel and assault, secondarily anti-monster and defense. The round ''mouth'' of the head; it fires only three-round bursts, which saves ammunition and widens the blast. Smoke, HEX and tear gas grenades are special ordnance, sold separately.'),
  ('ng-v41-viking', 2, '(Option A) Concealed Shoulder Mini-Missile Launchers (2)', 'By missile; plasma (1D6x10 M.D.) and armor piercing (1D4x10 M.D.) are standard', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2 or 4', '36 per launcher, 72 with both shoulders mini-missile', NULL, 'Anti-aircraft, anti-missile and assault, secondarily anti-armor and anti-monster. A rack behind an armored plate in each shoulder; the plate flips open, the missiles fire and it closes again. Both shoulders leave the factory the same type; one can be swapped for the other type for 70,000 credits. Mini-missiles cost 1,200-2,500 credits each by type (Rifts Ultimate Edition p.257).'),
  ('ng-v41-viking', 3, '(Option B) Concealed Shoulder Short-Range Missile Launchers (2)', 'By missile; standard loads are armor piercing (2D6x10 M.D., 5 ft/1.5 m radius) or plasma (2D6x10 M.D., 15 ft/4.6 m radius)', 1, 'Five miles (8 km)', 'One at a time or volleys of 2 or 4', '12 per launcher, 24 with both shoulders short-range', NULL, 'Anti-aircraft and assault, secondarily anti-armor and anti-monster. The longer-reaching fit for the same armored shoulder racks. Short-range missiles cost 2,000-4,500 credits each by type (Rifts Ultimate Edition p.256).'),
  ('ng-v41-viking', 4, 'NG-EV66 Heavy Plasma Cannon (1)', '1D6x10+6 M.D. per blast', 1, '2,500 ft (762 m)', 'Each shot is one of the gunner''s melee attacks', 'Unlimited on the nuclear power supply. Fuel cell models usually give the cannon its own four-cell Solid Oxide supply, good for 1D4 weeks of frequent use; battery models give it a battery of its own lasting 4D6+20 hours of frequent use, double with light use', NULL, 'Anti-aircraft and assault, secondarily anti-armor and anti-monster. The big gun on the right shoulder, with a 45 degree arc up and down and 20 degrees of traverse to either side.'),
  ('ng-v41-viking', 5, 'NG-L41 Concealed Arm Lasers (2)', '3D6 M.D. per single blast; no dual blast', 1, '2,000 ft (610 m)', 'Each shot is one melee attack', 'Effectively unlimited, or as long as an alternative power supply lasts', NULL, 'Anti-personnel and cutting, secondarily assault and defense. A small laser in each wrist that rises out of its housing to fire.'),
  ('ng-v41-viking', 6, 'Vibro-Claws (5)', '4D6 M.D. slash or stab with the Vibro-edge off; 6D6+4 M.D. with four or five blades out and the Vibro-Blades on', 1, '17 ft (5.2 m) reach', NULL, NULL, NULL, 'Anti-fortification and assault, secondarily labor and defense. A serrated blade extends from and retracts into each finger of both hands, for fighting, cutting, digging, mining and excavation.'),
  ('ng-v39-volcano', 1, 'NG-F139 Heavy Flamethrower', '1D4x10 M.D. to the target and to all others within 10 ft (3 m); 3D6 M.D. on diesel or gasoline. In a bunker, cave or unsealed vehicle, anyone caught without environmental gear or air must save vs poison or fall unconscious for 1D4 melee rounds', 1, '600 ft (183 m)', 'Each blast is one melee attack', 'About 140 blasts from a 260 gallon (984 liter) tank; refuels with military napalm, or diesel or gasoline at reduced damage', NULL, 'Anti-structure, anti-personnel and assault, secondarily anti-monster and defense. Over the right shoulder on a turret sweeping 120 degrees side to side with a 90 degree arc up and down; it throws gouts of burning napalm to flush troops from cover, gut bunkers, burn monster nests and start fires.'),
  ('ng-v39-volcano', 2, 'NG-E39 Plasma Ejector (1)', '6D6 M.D. per blast', 1, '1,600 ft (488 m); 400 ft (122 m) underwater', 'Each blast is one melee attack', 'Effectively unlimited', NULL, 'Anti-personnel and assault, secondarily anti-armor and defense. A simple point-and-shoot gun on the left forearm.'),
  ('ng-v39-volcano', 3, 'NG-HE139 Heatwave Emitter (1)', 'M.D.C. targets: 1 M.D. for each of the first two blasts, then 1D4 M.D. per further blast while the beam stays on. S.D.C. and Hit Point targets: 1 point per blast for the first two, then, held without a break, 1D4 for the third, 2D4, 2D6, 4D6, 8D6, 2D4x10, 2D6x10, 4D6x10, 1D4x100 and 1D6x100 for the fourth to twelfth, and 2D6x100 for the thirteenth and every blast after. Double damage against beings that heat or fire harms more; none to those immune, magic and psionic protection included', 1, '500 ft (152 m)', 'Up to four blasts, or one continuous beam counting as four, per melee round; each blast is one melee attack', 'Effectively unlimited on the robot''s power supply', NULL, 'Anti-personnel and assault, secondarily sabotage. NG''s experimental heat ray in the right forearm, heating the air in a narrow cylinder ahead of it. Damage builds only while the beam stays on one target: switching targets restarts the count, and a moving target needs a new strike roll each blast to keep it, so it is weak against M.D.C. armor and anything mobile but devastating to S.D.C. beings and material. Dry grass, straw, tinder, rags and exposed fuel ignite at one blast; hair and fur at three, clothing at five, plastic and rubber at six (softening at two); wood chars at three and burns at eight; water boils at three and flashes to steam at four; flesh is burned away at 10 and bone ashed at 36. It slowly melts M.D.C. locks, hinges, chains, wire, walls and doors, over minutes or hours. One blast at a thermal sensor or optic blanks it for 1D4 melee rounds; it also starts diversion fires, raises smoke cover and cooks wiring, switches or computers. Overload: after 12 blasts or 45 seconds of beam, a 5% chance per three melee rounds of overheating, rising to 10% at six rounds, 15% at nine, 20% at 12, 30% at 18, 50% at 30 and 100% at 60; overheated, it shuts itself off for 1D6x10 minutes, but if the failsafe fails (01-25%) it fires 2D6 more melee rounds (rolled secretly by the G.M.) and then burns out, doing 2D6x10 M.D. to the right arm and hand, freezing a surviving arm useless (-5% piloting), with a 01-02% chance the fuel tank explodes for 2D6x10 M.D. to the sensor head and main body.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 3 machines are in' AS assertion, count(*) AS got, 3 AS want
  FROM vehicles WHERE slug IN ('ng-v58-thundercaster', 'ng-v41-viking', 'ng-v39-volcano');
SELECT 'their 48 locations are in' AS assertion, count(*) AS got, 48 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-v58-thundercaster', 'ng-v41-viking', 'ng-v39-volcano');
SELECT 'their 12 weapon entries are in' AS assertion, count(*) AS got, 12 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-v58-thundercaster', 'ng-v41-viking', 'ng-v39-volcano');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-v58-thundercaster', 'ng-v41-viking', 'ng-v39-volcano') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

